 function dist(a,b,c,d){return Math.hypot(a-c,b-d)}
 function inIsland(x,y){return dist(x,y,world.x,world.y)<world.r-20}
 function placeResource(kind){for(let n=0;n<100;n++){let a=Math.random()*Math.PI*2,r=Math.sqrt(Math.random())*(world.r-55),x=world.x+Math.cos(a)*r,y=world.y+Math.sin(a)*r;if(dist(x,y,player.x,player.y)>90&&resources.every(q=>dist(q.x,q.y,x,y)>30)){resources.push({kind,x,y,got:false,pulse:Math.random()*6});return}}}
 function init(){world.x=0;world.y=0;world.r=270;player.x=0;player.y=0;player.wood=0;player.stone=0;player.level=1;resources=[];decor=[];particles=[];goal=20;
-  for(let i=0;i<18;i++)placeResource('wood');for(let i=0;i<9;i++)placeResource('stone');
+  for(let i=0;i<26;i++)placeResource('wood');for(let i=0;i<11;i++)placeResource('stone');
   for(let i=0;i<110;i++){let a=Math.random()*6.28,r=Math.sqrt(Math.random())*(world.r-18);decor.push({x:world.x+Math.cos(a)*r,y:world.y+Math.sin(a)*r,s:2+Math.random()*5,hue:Math.random()>.7?'rock':'grass'})}
 }
 init();
 function screen(){return {x:W/2+(player.x-player.x),y:H/2+(player.y-player.y)}}

