 function updateHUD(){document.getElementById('wood').textContent=player.wood;document.getElementById('stone').textContent=player.stone;document.getElementById('level').textContent=player.level;let pct=Math.min(100,player.wood/goal*100);document.getElementById('bar').style.width=pct+'%';document.getElementById('objective').textContent=player.wood>=goal?'Expand your land!':`Expand your land • gather ${goal-player.wood} wood`}
 function toast(t){let e=document.getElementById('toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1300)}
 function expand(){world.r+=95;player.level++;goal+=20;document.getElementById('panel').classList.add('show');document.getElementById('pTitle').textContent=`Level ${player.level}: Bigger Land!`;document.getElementById('pText').textContent=`Your island grew. Now gather ${goal-player.wood} wood to expand again.`;for(let i=0;i<15;i++)placeResource(i%4?'wood':'stone');updateHUD();toast('New territory unlocked!')}
 document.getElementById('pButton').onclick=()=>document.getElementById('panel').classList.remove('show');
-addEventListener('keydown',e=>keys[e.key.toLower]=true);addEventListener('keyup',e=>keys[e.key.toLower]=false);
+addEventListener('keydown',e=>keys[e.key.toLowerCase()]=true);addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
 canvas.addEventListener('pointermove',e=>{pointer.x=e.clientX;pointer.y=e.clientY});canvas.addEventListener('pointerdown',e=>{pointer.down=true;pointer.x=e.clientX;pointer.y=e.clientY});addEventListener('pointerup',()=>pointer.down=false);
 const joy=document.getElementById('joy'),knob=document.getElementById('knob');let activeJoy=false,jid=null;
 function moveJoy(e){if(!activeJoy)return;let r=joy.getBoundingClientRect(),x=e.clientX-(r.left+r.width/2),y=e.clientY-(r.top+r.height/2),l=Math.hypot(x,y),m=34;if(l>m){x=x/l*m;y=y/l*m}knob.style.transform=`translate(${x}px,${y}px)`;joyX=x/m;joyY=y/m}
 joy.addEventListener('pointerdown',e=>{activeJoy=true;jid=e.pointerId;joy.setPointerCapture(jid);moveJoy(e)});joy.addEventListener('pointermove',moveJoy);joy.addEventListener('pointerup',()=>{activeJoy=false;joyX=0;joyY=0;knob.style.transform='translate(0,0)'});

